fetch(layer.data)
            .then(r => r.json())
            .then(geojson => {
              if (map.current?.getSource(sourceId)) return;
              map.current?.addSource(sourceId, { type: 'geojson', data: geojson });
              map.current?.addLayer({
                id: `layer-${layer.id}`,
                type: 'fill',
                source: sourceId,
                paint: {
                  'fill-color': '#8B4513',
                  'fill-opacity': layer.opacity * 0.5,
                },
              });
              map.current?.addLayer({
                id: `layer-${layer.id}-outline`,
                type: 'line',
                source: sourceId,
                paint: {
                  'line-color': '#A0522D',
                  'line-width': 1,
                },
              });
            })
            .catch

fetch(url)
      .then(r => r.json())
      .then(geojson => {
        if (!map.current) return;
        map.current.addSource('source-macrostrat-geology', { type: 'geojson', data: geojson });
        map.current.addLayer({
          id: 'layer-macrostrat-geology',
          type: 'fill',
          source: 'source-macrostrat-geology',
          paint: {
            'fill-color': [
              'match', ['get', 'lith'],
              'shale', '#7B8794',
              'sandstone', '#D4A574',
              'limestone', '#B8C4AE',
              'granite', '#C9725A',
              'basalt', '#5A5A5A',
              '#8B7355' // default
            ],
            'fill-opacity': 0.55,
          },
        });
        map.current.addLayer({
          id: 'layer-macrostrat-geology-outline',
          type: 'line',
          source: 'source-macrostrat-geology',
          paint: { 'line-color': '#A0522D', 'line-width': 0.5 },
        });
      })
      .catch

